#!/bin/sh
set -eu
[ "$#" -eq 5 ] || exit 2
launcher_command=$1
unset T4_TOOLCHAIN_CARGO T4_TOOLCHAIN_RUSTC t4_nightly_cargo t4_nightly_rustc \
    P11SCOPE_PRODUCT_BUILD_MODE P11SCOPE_PREPARED_STABLE_CARGO \
    P11SCOPE_PREPARED_STABLE_RUSTC P11SCOPE_PREPARED_BPF_CARGO \
    P11SCOPE_PREPARED_BPF_RUSTC
T4_TOOLCHAIN_CARGO=$2
T4_TOOLCHAIN_RUSTC=$3
t4_nightly_cargo=$4
t4_nightly_rustc=$5
CANARY_WORK=$P11SCOPE_TASK4_WORK
ATTACH_WORK=$P11SCOPE_TASK4_WORK
. "$launcher_command"
